-- Las Cajas PR pasan a llamarse "muestras" y las muestras de antes,
-- producto por producto, "productos sueltos" (pedido del 2026-10-19: "ya no
-- son PR sino muestras"; se dejan las dos con nombres distintos). Solo se
-- cambia el nombre o el texto que sigue igual al de fábrica: lo que el admin
-- ya editó en Admin → Notificaciones no se toca (ver bootstrap.ts).
UPDATE "NotificationTypeConfig" SET "label" = 'Producto suelto aprobado', "updatedAt" = CURRENT_TIMESTAMP WHERE "key" = 'SAMPLE_APPROVED' AND "label" = 'Muestra aprobada';
UPDATE "NotificationTypeConfig" SET "messageTemplate" = '{marca} aprobó tu pedido de "{producto}" y pronto te lo envía.', "updatedAt" = CURRENT_TIMESTAMP WHERE "key" = 'SAMPLE_APPROVED' AND "messageTemplate" = '{marca} aprobó tu muestra de "{producto}" y pronto te la envía.';
UPDATE "NotificationTypeConfig" SET "label" = 'Producto suelto rechazado', "updatedAt" = CURRENT_TIMESTAMP WHERE "key" = 'SAMPLE_REJECTED' AND "label" = 'Muestra rechazada';
UPDATE "NotificationTypeConfig" SET "messageTemplate" = '{marca} no puede enviarte "{producto}" esta vez.{razon}', "updatedAt" = CURRENT_TIMESTAMP WHERE "key" = 'SAMPLE_REJECTED' AND "messageTemplate" = '{marca} no puede enviarte la muestra de "{producto}" esta vez.{razon}';
UPDATE "NotificationTypeConfig" SET "label" = 'Una marca te ofreció un producto suelto', "updatedAt" = CURRENT_TIMESTAMP WHERE "key" = 'SAMPLE_OFFERED' AND "label" = 'Una marca te ofreció una muestra';
UPDATE "NotificationTypeConfig" SET "messageTemplate" = '{marca} te quiere regalar "{producto}". Acéptalo en Solicitar muestras y déjale tu dirección de envío.', "updatedAt" = CURRENT_TIMESTAMP WHERE "key" = 'SAMPLE_OFFERED' AND "messageTemplate" = '{marca} te quiere regalar "{producto}". Acéptala en Solicitar muestras y déjale tu dirección de envío.';
UPDATE "NotificationTypeConfig" SET "label" = 'Una marca te propuso su muestra', "updatedAt" = CURRENT_TIMESTAMP WHERE "key" = 'PR_BOX_PROPOSED' AND "label" = 'Una marca te propuso su Caja PR';
UPDATE "NotificationTypeConfig" SET "messageTemplate" = '{marca} te propone su muestra "{caja}". Mira el brief y acéptala en Solicitar muestras.', "updatedAt" = CURRENT_TIMESTAMP WHERE "key" = 'PR_BOX_PROPOSED' AND "messageTemplate" = '{marca} te propone su Caja PR "{caja}". Mira el brief y acéptala en Marketplace → Cajas PR.';
UPDATE "NotificationTypeConfig" SET "label" = 'Muestra aprobada', "updatedAt" = CURRENT_TIMESTAMP WHERE "key" = 'PR_BOX_APPROVED' AND "label" = 'Caja PR aprobada';
UPDATE "NotificationTypeConfig" SET "messageTemplate" = '{marca} aprobó tu muestra "{caja}". {detalle}', "updatedAt" = CURRENT_TIMESTAMP WHERE "key" = 'PR_BOX_APPROVED' AND "messageTemplate" = '{marca} aprobó tu Caja PR "{caja}". {detalle}';
UPDATE "NotificationTypeConfig" SET "label" = 'Muestra no aprobada', "updatedAt" = CURRENT_TIMESTAMP WHERE "key" = 'PR_BOX_REJECTED' AND "label" = 'Caja PR no aprobada';
UPDATE "NotificationTypeConfig" SET "messageTemplate" = '{marca} no puede enviarte la muestra "{caja}" esta vez.{razon}', "updatedAt" = CURRENT_TIMESTAMP WHERE "key" = 'PR_BOX_REJECTED' AND "messageTemplate" = '{marca} no puede enviarte la Caja PR "{caja}" esta vez.{razon}';
UPDATE "NotificationTypeConfig" SET "label" = 'Una creadora pidió un producto suelto', "updatedAt" = CURRENT_TIMESTAMP WHERE "key" = 'SAMPLE_REQUESTED' AND "label" = 'Una creadora solicitó una muestra';
UPDATE "NotificationTypeConfig" SET "messageTemplate" = '{creador} quiere probar "{producto}". Apruébalo o recházalo en Muestras.', "updatedAt" = CURRENT_TIMESTAMP WHERE "key" = 'SAMPLE_REQUESTED' AND "messageTemplate" = '{creador} quiere probar "{producto}". Aprueba o rechaza la muestra en Muestras.';
UPDATE "NotificationTypeConfig" SET "label" = 'Una creadora aceptó tu producto suelto', "updatedAt" = CURRENT_TIMESTAMP WHERE "key" = 'SAMPLE_OFFER_ACCEPTED' AND "label" = 'Una creadora aceptó tu oferta de muestra';
UPDATE "NotificationTypeConfig" SET "messageTemplate" = '{creador} aceptó "{producto}". Ya está en Pedidos, listo para despachar.', "updatedAt" = CURRENT_TIMESTAMP WHERE "key" = 'SAMPLE_OFFER_ACCEPTED' AND "messageTemplate" = '{creador} aceptó tu muestra de "{producto}". Ya está en Pedidos, lista para despachar.';
UPDATE "NotificationTypeConfig" SET "label" = 'Una creadora pidió tu muestra', "updatedAt" = CURRENT_TIMESTAMP WHERE "key" = 'PR_BOX_REQUESTED' AND "label" = 'Una creadora pidió tu Caja PR';
UPDATE "NotificationTypeConfig" SET "messageTemplate" = '{creador} pidió tu muestra "{caja}". Apruébala o recházala en Muestras.', "updatedAt" = CURRENT_TIMESTAMP WHERE "key" = 'PR_BOX_REQUESTED' AND "messageTemplate" = '{creador} pidió tu Caja PR "{caja}". Apruébala o recházala en Muestras.';
UPDATE "NotificationTypeConfig" SET "label" = 'Una creadora aceptó tu muestra', "updatedAt" = CURRENT_TIMESTAMP WHERE "key" = 'PR_BOX_ACCEPTED' AND "label" = 'Una creadora aceptó tu Caja PR';
UPDATE "NotificationTypeConfig" SET "messageTemplate" = '{creador} aceptó tu muestra "{caja}". Ya puedes enviarla: la dirección está en Muestras.', "updatedAt" = CURRENT_TIMESTAMP WHERE "key" = 'PR_BOX_ACCEPTED' AND "messageTemplate" = '{creador} aceptó tu Caja PR "{caja}". Ya puedes enviarla: la dirección está en Muestras.';
UPDATE "NotificationTypeConfig" SET "label" = 'Una creadora no aceptó tu muestra', "updatedAt" = CURRENT_TIMESTAMP WHERE "key" = 'PR_BOX_DECLINED' AND "label" = 'Una creadora no aceptó tu Caja PR';
UPDATE "NotificationTypeConfig" SET "messageTemplate" = '{creador} no aceptó tu muestra "{caja}".', "updatedAt" = CURRENT_TIMESTAMP WHERE "key" = 'PR_BOX_DECLINED' AND "messageTemplate" = '{creador} no aceptó tu Caja PR "{caja}".';
UPDATE "NotificationTypeConfig" SET "label" = 'Una creadora publicó con tu muestra', "updatedAt" = CURRENT_TIMESTAMP WHERE "key" = 'PR_BOX_PUBLISHED' AND "label" = 'Una creadora publicó con tu Caja PR';
UPDATE "NotificationTypeConfig" SET "messageTemplate" = '{creador} publicó su contenido con tu muestra "{caja}": {link}', "updatedAt" = CURRENT_TIMESTAMP WHERE "key" = 'PR_BOX_PUBLISHED' AND "messageTemplate" = '{creador} publicó su contenido con tu Caja PR "{caja}": {link}';
